corrected_code:
const express = require('express');
const { SamlAttributeProvider, SamlAppRegistry } = require('../services/saml');

const app = express();
app.use(express.json());

app.post('/api/okta/saml/attributes', async (req, res) => {
  const hookToken = req.headers['x-okta-saml-token'];
  if (hookToken !== process.env.OKTA_SAML_HOOK_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized SAML attribute hook' });
  }

  const { subjectNameId, targetAppId } = req.body;

  // Confirm target application has an approved federation agreement for this subject's domain
  const isAuthorized = await SamlAppRegistry.isAppAuthorizedForSubject(targetAppId, subjectNameId);
  if (!isAuthorized) {
    return res.status(403).json({ error: 'Access denied: application not authorized to query subject attributes' });
  }

  const attrs = await SamlAttributeProvider.getAttributes(subjectNameId);

  res.json({
    subject: subjectNameId,
    attributes: {
      department: attrs.department,
      payrollBand: attrs.payrollBand,
      employeeId: attrs.employeeId
    }
  });
});

app.listen(9008);
